export { LineChart, type LineChartProps } from "./line";
export { AreaChart, type AreaChartProps } from "./area";
export { BarChart, type BarChartProps, type BarOrientation } from "./bar";
export { ScatterChart, type ScatterChartProps } from "./scatter";
export { Donut, Share, type DonutProps, type ShareProps, type ShareSlice } from "./donut";
export { Histogram, type HistogramProps, type HistogramBin } from "./histogram";
export { SmallMultiples, type SmallMultiplesProps, type SmallMultiple } from "./multiples";
export { Sparkline, type SparklineProps } from "./sparkline";
export type { ChartSeries, ChartAnnotation, ChartPoint } from "./frame";

"use client";

import * as React from "react";
import {
  ChartCanvas,
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  LegendSwatch,
  MAX_SERIES,
  PLOT,
  SrTable,
  areaMark,
  chartStyles,
  defaultFormat,
  describePlot,
  lineMark,
  niceMax,
  plotName,
  plotProps,
  stackedRows,
  stepCursor,
  ticksBetween,
  useChartWidth,
  type ChartAnnotation,
  type ChartSeries,
} from "./frame";
import { rs } from "../rs";

export interface LineChartProps extends React.HTMLAttributes<HTMLDivElement> {
  series: ChartSeries[];
  labels?: string[];
  height?: number;
  /** Fill under the first series. Prefer AreaChart for a dedicated area. */
  area?: boolean;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  xLabel?: string;
  annotations?: ChartAnnotation[];
  domain?: [number, number];
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
  /** BCP 47 tag for number formatting; undefined is the reader's own. */
  locale?: string;
}

export const LineChart = React.forwardRef<HTMLDivElement, LineChartProps>(function LineChart({
  series,
  labels,
  height = 204,
  area,
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  xLabel,
  annotations,
  domain,
  spot,
  valueFormat,
  locale,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: LineChartProps, ref: React.ForwardedRef<HTMLDivElement>) {
  const shown = series.slice(0, MAX_SERIES);
  const n = Math.max(0, ...shown.map((s) => s.values.length));
  const stacks = stacked ? stackedRows(shown) : null;
  const extent = (stacks ? stacks.flat() : shown.flatMap((s) => s.values)).filter((v): v is number => typeof v === "number" && Number.isFinite(v));
  const validDomain = domain?.every(Number.isFinite) && domain[0] !== domain[1] ? domain : undefined;
  const min = validDomain ? Math.min(...validDomain) : Math.min(0, ...extent);
  const max = validDomain ? Math.max(...validDomain) : niceMax(Math.max(0, ...extent));
  const span = max - min || 1;
  const format = valueFormat ?? ((v: number) => defaultFormat(v, undefined, locale));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit, locale));
  const [hover, setHover] = React.useState<number | null>(null);
  const overlayRef = React.useRef<SVGRectElement>(null);
  const [canvasRef, W] = useChartWidth<HTMLDivElement>();
  const titleId = React.useId();
  const clipId = React.useId();

  const { ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const x = (i: number) => ML + (n <= 1 ? 0 : (i / (n - 1)) * plotW);
  const y = (v: number) => {
    const t = (v - min) / span;
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const segments = (values: Array<number | null>) => {
    const groups: Array<Array<{ v: number; i: number }>> = [];
    let current: Array<{ v: number; i: number }> = [];
    values.forEach((v, i) => {
      if (typeof v === "number" && Number.isFinite(v)) current.push({ v, i });
      else if (current.length) { groups.push(current); current = []; }
    });
    if (current.length) groups.push(current);
    return groups;
  };
  const path = (values: Array<number | null>, fill = false) => segments(values).map((group) =>
    group.map(({ v, i }, j) => `${j ? "L" : "M"}${x(i)} ${y(v)}`).join(" ") +
    (fill ? ` L${x(group[group.length - 1]!.i)} ${y(Math.max(min, Math.min(max, 0)))} L${x(group[0]!.i)} ${y(Math.max(min, Math.min(max, 0)))} Z` : "")
  ).join(" ");
  const tickVals = ticksBetween(min, max, ticks);
  const tickLabels = Array.from({ length: n }, (_, i) => labels?.[i] ?? `${i + 1}`);

  const locate = (clientX: number): number | null => {
    const rect = overlayRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0 || !extent.length) return null;
    const ratio = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    return Math.round(ratio * (n - 1));
  };

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const cursor = rs(["rs-chart-cursor"], chartStyles.cursor);
  const ann = rs(["rs-chart-ann"], chartStyles.ann);
  const dot = rs(["rs-chart-dot"], chartStyles.dot);

  const name = plotName(
    { "aria-label": ariaLabel, "aria-labelledby": ariaLabelledBy },
    yLabel ? titleId : undefined,
    describePlot(area ? "Area chart" : "Line chart", shown.map((s) => s.name), unit),
  );
  const a11y = plotProps(
    name,
    (key) => {
      const next = stepCursor(key, hover, extent.length ? n : 0);
      if (next === undefined) return false;
      setHover(next);
      return true;
    },
    () => setHover(null),
  );

  return (
    <ChartField ref={ref} spot={spot} className={className} {...props}>
      {!extent.length && <p role="status">No data to display</p>}
      {(yLabel || xLabel) && (
        <ChartHead>
          {yLabel ? <ChartTitle id={titleId}>{yLabel}</ChartTitle> : <span />}
          {xLabel ? <ChartTitle>{xLabel}</ChartTitle> : null}
        </ChartHead>
      )}
      <ChartCanvas ref={canvasRef}>
        <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} {...a11y}>
          <defs><clipPath id={clipId}><rect x={ML} y={MT} width={plotW} height={plotH} /></clipPath></defs>
          <g className={plot.className} style={plot.style} aria-hidden="true">
            {grid &&
              tickVals.map((t) => (
                <g key={t}>
                  <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={y(t)} y2={y(t)} />
                  <text className={axis.className} style={axis.style} x={ML - 6} y={y(t) + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              ))}
            <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={y(min)} y2={y(min)} />
            {area && shown[0] && !stacked && (
              <path {...areaMark(Boolean(spot))} clipPath={`url(#${clipId})`} d={path(shown[0].values, true)} />
            )}
            {stacked && stacks
              ? shown.map((s, si) => {
                  const top = stacks.map((row) => row[si] ?? 0);
                  return <path key={s.name} {...lineMark(si, Boolean(spot))} clipPath={`url(#${clipId})`} d={path(top)} />;
                })
              : shown.map((s, si) => <path key={s.name} {...lineMark(si, Boolean(spot))} clipPath={`url(#${clipId})`} d={path(s.values)} />)}
            {annotations?.map((a) => (
              <g key={`${a.at}-${a.label}`}>
                <line className={cursor.className} style={cursor.style} x1={x(a.at)} x2={x(a.at)} y1={MT} y2={y(min)} />
                <text className={ann.className} style={ann.style} x={x(a.at) + 4} y={MT + 10}>
                  {a.label}
                </text>
              </g>
            ))}
            {hover != null && hover < n && extent.length > 0 && (
              <g>
                <line className={cursor.className} style={cursor.style} x1={x(hover)} x2={x(hover)} y1={MT} y2={y(min)} />
                {shown.map((s, si) => typeof s.values[hover] === "number" && Number.isFinite(s.values[hover]) ? (
                  <circle
                    key={si}
                    className={dot.className}
                    style={dot.style}
                    cx={x(hover)}
                    cy={y(stacked && stacks ? (stacks[hover]?.[si] ?? 0) : (s.values[hover] ?? 0))}
                    r={3}
                    clipPath={`url(#${clipId})`}
                  />
                ) : null)}
              </g>
            )}
            <text className={axis.className} style={axis.style} x={ML} y={height - 4} textAnchor="start">
              {tickLabels[0]}
            </text>
            <text className={axis.className} style={axis.style} x={W - MR} y={height - 4} textAnchor="end">
              {tickLabels[n - 1]}
            </text>
            <rect
              ref={overlayRef}
              x={ML}
              y={0}
              width={plotW}
              height={height}
              fill="transparent"
              onPointerMove={(e) => setHover(locate(e.clientX))}
              onPointerLeave={() => setHover(null)}
            />
          </g>
        </svg>
        {hover != null && hover < n && extent.length > 0 && (
          <ChartTip
            left={x(hover)}
            top={MT}
            label={tickLabels[hover] ?? ""}
            rows={shown.map((s) => ({ name: s.name, value: s.values[hover] != null && Number.isFinite(s.values[hover]) ? tip(s.values[hover]!) : "No data" }))}
          />
        )}
      </ChartCanvas>
      {(shown.length > 1 || unit) && (
        <ChartLegend>
          {shown.map((s, si) => (
            <ChartLegendItem key={s.name}>
              <LegendSwatch seriesIndex={si} spot={Boolean(spot)} />
              {s.name}
            </ChartLegendItem>
          ))}
          {unit ? <ChartLegendItem>{unit}</ChartLegendItem> : null}
        </ChartLegend>
      )}
      <SrTable caption={yLabel ?? describePlot("Chart data", shown.map((s) => s.name), unit)} labels={tickLabels} series={shown} />
    </ChartField>
  );
});

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak } from "../tokens.stylex";
import { LineChart, type LineChartProps } from "./line";

const styles = stylex.create({
  area: {
    borderRadius: 0,
    boxShadow: "none",
    backgroundColor: vlak.paper,
  },
});

export type AreaChartProps = Omit<LineChartProps, "area">;

/** Filled field. Same law as the line: hairlines, texture, one optional spot. */
export const AreaChart = React.forwardRef<HTMLDivElement, AreaChartProps>(function AreaChart(props, ref) {
  void styles.area;
  return <LineChart ref={ref} {...props} area />;
});

"use client";

import * as React from "react";
import {
  ChartCanvas,
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  PLOT,
  SrTable,
  barMark,
  chartStyles,
  defaultFormat,
  describePlot,
  niceMax,
  plotName,
  plotProps,
  stackedRows,
  stepCursor,
  ticksBetween,
  useChartWidth,
  type ChartSeries,
} from "./frame";
import { rs } from "../rs";

export type BarOrientation = "vertical" | "horizontal";

export interface BarChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data?: Array<{ label: string; value: number }>;
  series?: ChartSeries[];
  labels?: string[];
  height?: number;
  orientation?: BarOrientation;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
  /** BCP 47 tag for number formatting; undefined is the reader's own. */
  locale?: string;
}

export const BarChart = React.forwardRef<HTMLDivElement, BarChartProps>(function BarChart({
  data,
  series,
  labels,
  height = 204,
  orientation = "vertical",
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  spot,
  valueFormat,
  locale,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: BarChartProps, ref: React.ForwardedRef<HTMLDivElement>) {
  const fromData: ChartSeries[] = data ? [{ name: "Value", values: data.map((d) => d.value) }] : [];
  const shown = (series ?? fromData).slice(0, 4);
  const n = Math.max(0, labels?.length ?? 0, ...shown.map((s) => s.values.length));
  const tickLabels = Array.from({ length: n }, (_, i) => labels?.[i] ?? data?.[i]?.label ?? `${i + 1}`);
  const stacks = stacked && shown.length > 1 ? stackedRows(shown) : null;
  const extent = (stacks ? stacks.flat() : shown.flatMap((s) => s.values)).filter((v): v is number => typeof v === "number" && Number.isFinite(v));
  const min = Math.min(0, ...extent);
  const max = niceMax(Math.max(0, ...extent));
  const format = valueFormat ?? ((v: number) => defaultFormat(v, undefined, locale));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit, locale));
  const [hover, setHover] = React.useState<number | null>(null);
  const hoverSample = hover == null ? 0 : shown[0]?.values[hover];
  const hoverValue = typeof hoverSample === "number" && Number.isFinite(hoverSample) ? hoverSample : 0;
  const [canvasRef, W] = useChartWidth<HTMLDivElement>();
  const titleId = React.useId();

  const { ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const horizontal = orientation === "horizontal";
  const band = (horizontal ? plotH : plotW) / Math.max(1, n);
  const barThick = Math.min(8, Math.max(1, band / (stacked ? 1 : shown.length || 1) - 2));
  const inset = (band - barThick) / 2;
  const yV = (v: number) => {
    const t = (v - min) / (max - min);
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const xV = (v: number) => ML + (inverted ? 1 - (v - min) / (max - min) : (v - min) / (max - min)) * plotW;
  const tickVals = ticksBetween(min, max, ticks);
  const labelEvery = Math.ceil(n / 8);

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);

  const name = plotName(
    { "aria-label": ariaLabel, "aria-labelledby": ariaLabelledBy },
    yLabel ? titleId : undefined,
    describePlot("Bar chart", shown.map((s) => s.name), unit),
  );
  const a11y = plotProps(
    name,
    (key) => {
      const next = stepCursor(key, hover, extent.length ? n : 0);
      if (next === undefined) return false;
      setHover(next);
      return true;
    },
    () => setHover(null),
  );
  const hoverProps = (i: number) => ({
    onPointerEnter: () => setHover(i),
    onPointerLeave: () => setHover(null),
  });

  return (
    <ChartField ref={ref} spot={spot} className={className} {...props}>
      {!extent.length && <p role="status">No data to display</p>}
      {yLabel && (
        <ChartHead>
          <ChartTitle id={titleId}>{yLabel}</ChartTitle>
        </ChartHead>
      )}
      <ChartCanvas ref={canvasRef}>
        <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} {...a11y}>
          <g className={plot.className} style={plot.style} aria-hidden="true">
            {grid &&
              tickVals.map((t) =>
                horizontal ? (
                  <g key={t}>
                    <line className={gridSx.className} style={gridSx.style} x1={xV(t)} x2={xV(t)} y1={MT} y2={height - MB} />
                    <text className={axis.className} style={axis.style} x={xV(t)} y={height - 4} textAnchor="middle">
                      {format(t)}
                    </text>
                  </g>
                ) : (
                  <g key={t}>
                    <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={yV(t)} y2={yV(t)} />
                    <text className={axis.className} style={axis.style} x={ML - 6} y={yV(t) + 3.5} textAnchor="end">
                      {format(t)}
                    </text>
                  </g>
                ),
              )}
            {tickLabels.map((label, i) => {
              let positive = 0;
              let negative = 0;
              return shown.map((s, si) => {
                const value = s.values[i];
                if (typeof value !== "number" || !Number.isFinite(value)) return null;
                const before = stacked ? value < 0 ? negative : positive : 0;
                if (value < 0) negative += value; else positive += value;
                const after = before + value;
                const a = horizontal ? xV(before) : yV(before);
                const b = horizontal ? xV(after) : yV(after);
                const offset = stacked ? inset : (band - shown.length * (barThick + 2)) / 2 + si * (barThick + 2);
                const mark = barMark({ spot: Boolean(spot) && si === 0, muted: hover != null && hover !== i });
                return <rect
                  key={`${i}-${si}`}
                  {...mark}
                  data-series={s.name}
                  opacity={1 - si * 0.18}
                  x={horizontal ? Math.min(a, b) : ML + i * band + offset}
                  y={horizontal ? MT + i * band + offset : Math.min(a, b)}
                  width={horizontal ? Math.abs(b - a) : barThick}
                  height={horizontal ? barThick : Math.abs(b - a)}
                  {...hoverProps(i)}
                />;
              });
            })}
            <line
              className={baseline.className}
              style={baseline.style}
              x1={horizontal ? xV(0) : ML}
              x2={horizontal ? xV(0) : W - MR}
              y1={horizontal ? MT : yV(0)}
              y2={horizontal ? height - MB : yV(0)}
            />
            {tickLabels.map(
              (label, i) =>
                i % labelEvery === 0 && (
                  <text
                    key={label}
                    className={axis.className}
                    style={axis.style}
                    x={horizontal ? ML - 6 : ML + i * band + band / 2}
                    y={horizontal ? MT + i * band + band / 2 + 3 : height - 4}
                    textAnchor={horizontal ? "end" : "middle"}
                  >
                    {label}
                  </text>
                ),
            )}
          </g>
        </svg>
        {hover != null && tickLabels[hover] && (
          <ChartTip
            left={horizontal ? ML + (xV(hoverValue) - ML) / 2 : ML + hover * band + band / 2}
            top={horizontal ? MT + hover * band + inset : yV(hoverValue)}
            label={tickLabels[hover]}
            rows={shown.map((s) => ({ name: shown.length > 1 ? s.name : undefined, value: Number.isFinite(s.values[hover]) && s.values[hover] != null ? tip(s.values[hover]!) : "No data" }))}
          />
        )}
      </ChartCanvas>
      {(unit || shown.length > 1) && (
        <ChartLegend aria-hidden="true">
          {shown.length > 1 && shown.map((s, i) => <ChartLegendItem key={s.name}><svg width="8" height="8" aria-hidden="true"><rect width="8" height="8" {...barMark({ spot: Boolean(spot) && i === 0 })} opacity={1 - i * 0.18} /></svg>{s.name}</ChartLegendItem>)}
          {unit && <ChartLegendItem>{unit}</ChartLegendItem>}
        </ChartLegend>
      )}
      <SrTable caption={yLabel ?? describePlot("Chart data", shown.map((s) => s.name), unit)} labels={tickLabels} series={shown} />
    </ChartField>
  );
});

"use client";

import * as React from "react";
import {
  ChartCanvas,
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  LegendSwatch,
  PLOT,
  SrTable,
  chartStyles,
  defaultFormat,
  describePlot,
  plotName,
  plotProps,
  scatterMark,
  stepCursor,
  ticksBetween,
  useChartWidth,
  type ChartAnnotation,
  type ChartPoint,
} from "./frame";
import { rs } from "../rs";

export type ScatterChartProps = React.HTMLAttributes<HTMLDivElement> & {
  points: ChartPoint[];
  height?: number;
  unit?: string;
  xLabel?: string;
  yLabel?: string;
  xDomain?: [number, number];
  yDomain?: [number, number];
  grid?: boolean;
  ticks?: number;
  annotations?: ChartAnnotation[];
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
  /** BCP 47 tag for number formatting; undefined is the reader's own. */
  locale?: string;
};

function extent(values: number[], pad = 0.08): [number, number] {
  if (!values.length) return [0, 1];
  const lo = Math.min(...values);
  const hi = Math.max(...values);
  const span = hi - lo || 1;
  return [lo - span * pad, hi + span * pad];
}

export const ScatterChart = React.forwardRef<HTMLDivElement, ScatterChartProps>(function ScatterChart({
  points: inputPoints,
  height = 204,
  unit,
  xLabel,
  yLabel,
  xDomain,
  yDomain,
  grid = true,
  ticks = 4,
  annotations = [],
  valueFormat,
  className,
  spot,
  locale,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: ScatterChartProps, ref: React.ForwardedRef<HTMLDivElement>) {
  const points = inputPoints.filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  const format = valueFormat ?? ((v: number) => defaultFormat(v, undefined, locale));
  const [hover, setHover] = React.useState<number | null>(null);
  const [canvasRef, W] = useChartWidth<HTMLDivElement>();
  const titleId = React.useId();
  const { ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const safeDomain = (domain: [number, number] | undefined, fallback: [number, number]): [number, number] => domain?.every(Number.isFinite) && domain[0] !== domain[1] ? [Math.min(...domain), Math.max(...domain)] : fallback;
  const [xMin, xMax] = safeDomain(xDomain, extent(xs));
  const [yMin, yMax] = safeDomain(yDomain, extent(ys));
  const yTicks = ticksBetween(yMin, yMax, ticks);
  const xTicks = ticksBetween(xMin, xMax, ticks);
  const toX = (x: number) => ML + ((x - xMin) / (xMax - xMin || 1)) * plotW;
  const toY = (y: number) => MT + plotH - ((y - yMin) / (yMax - yMin || 1)) * plotH;
  const groups = [...new Set(points.map((p) => p.group).filter(Boolean))] as string[];
  const active = hover != null ? points[hover] : null;

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const cursor = rs(["rs-chart-cursor"], chartStyles.cursor);
  const ann = rs(["rs-chart-ann"], chartStyles.ann);
  const mark = scatterMark(Boolean(spot));

  const name = plotName(
    { "aria-label": ariaLabel, "aria-labelledby": ariaLabelledBy },
    yLabel ? titleId : undefined,
    describePlot("Scatter chart", [xLabel ?? `${points.length} points`, ...(yLabel ? [yLabel] : [])], unit),
  );
  const a11y = plotProps(
    name,
    (key) => {
      const next = stepCursor(key, hover, points.length);
      if (next === undefined) return false;
      setHover(next);
      return true;
    },
    () => setHover(null),
  );

  return (
    <ChartField ref={ref} spot={spot} className={className} {...props}>
      {!points.length && <p role="status">No data to display</p>}
      {(yLabel || xLabel) && (
        <ChartHead>
          {yLabel ? <ChartTitle id={titleId}>{yLabel}</ChartTitle> : <span />}
          {xLabel ? <ChartTitle>{xLabel}</ChartTitle> : null}
        </ChartHead>
      )}
      <ChartCanvas ref={canvasRef}>
        <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} {...a11y}>
          <g className={plot.className} style={plot.style} aria-hidden="true">
            {grid &&
              yTicks.map((t) => (
                <g key={`yg-${t}`}>
                  <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={toY(t)} y2={toY(t)} />
                  <text className={axis.className} style={axis.style} x={ML - 6} y={toY(t) + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              ))}
            {grid &&
              xTicks.map((t) => (
                <line key={`xg-${t}`} className={gridSx.className} style={gridSx.style} x1={toX(t)} x2={toX(t)} y1={MT} y2={MT + plotH} />
              ))}
            <line className={baseline.className} style={baseline.style} x1={ML} x2={ML} y1={MT} y2={MT + plotH} />
            <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
            {xTicks.map((t) => (
              <text key={`xl-${t}`} className={axis.className} style={axis.style} x={toX(t)} y={height - 4} textAnchor="middle">
                {format(t)}
              </text>
            ))}
            {annotations.map((a) => (
              <g key={`${a.at}-${a.label}`}>
                <line className={cursor.className} style={cursor.style} x1={toX(a.at)} x2={toX(a.at)} y1={MT} y2={MT + plotH} />
                <text className={ann.className} style={ann.style} x={toX(a.at) + 4} y={MT + 10}>
                  {a.label}
                </text>
              </g>
            ))}
            {points.map((p, i) => (
              <circle
                key={i}
                className={mark.className}
                style={mark.style}
                cx={toX(p.x)}
                cy={toY(p.y)}
                r={hover === i ? 3.5 : 2.25}
                onPointerEnter={() => setHover(i)}
                onPointerLeave={() => setHover(null)}
              />
            ))}
          </g>
        </svg>
        {active && (
          <ChartTip
            left={toX(active.x)}
            top={toY(active.y)}
            label={active.label ?? `${format(active.x)} · ${format(active.y)}`}
            rows={[{ name: active.group, value: format(active.y) }]}
          />
        )}
      </ChartCanvas>
      {(groups.length > 0 || unit) && (
        <ChartLegend aria-hidden="true">
          {groups.map((g) => (
            <ChartLegendItem key={g}>
              <LegendSwatch seriesIndex={0} spot={Boolean(spot)} />
              {g}
            </ChartLegendItem>
          ))}
          {unit ? <ChartLegendItem>{unit}</ChartLegendItem> : null}
        </ChartLegend>
      )}
      <SrTable
        caption={yLabel ?? "Scatter data"}
        labels={points.map((p) => p.label ?? `${p.x}`)}
        series={[
          { name: xLabel ?? "x", values: points.map((p) => p.x) },
          { name: yLabel ?? "y", values: points.map((p) => p.y) },
          ...(groups.length ? [{ name: "Group", values: points.map((p) => p.group ?? "") }] : []),
        ]}
      />
    </ChartField>
  );
});

