    gridTemplateColumns: "repeat(auto-fill, minmax(184px, 1fr))",
    gap: "1.25rem",
  },
  item: { margin: 0, minWidth: 0 },
  cap: {
    marginTop: 0,
    marginInlineEnd: 0,
    marginBottom: "0.5rem",
